//ВЫБРАТЬ РАЗРЕШЕННЫЕ
//	//ВТ.Ссылка КАК ДокументЗаказ,
//	ВЫРАЗИТЬ(ВТ.ЗаказНаПроизводство КАК Документ.ЗаказПокупателя) КАК ДокументЗаказ,
//	ВТ.Номенклатура КАК Номенклатура,
//	ВТ.ХарактеристикаНоменклатуры,
//	ВТ.СерияНоменклатуры,
//	//СУММА(ВТ.Количество * ВТ.Коэффициент) КАК Заказано,
//	ЕСТЬNULL(ТоварыНаСкладахОстатки.КоличествоОстаток, 0) КАК КоличествоОстаток,
//	//ЕСТЬNULL(ЗаказыПокупателейОстатки.КоличествоОстаток, 0) КАК Потребность,
//	ЕСТЬNULL(ВТ.КоличествоОстаток, 0) КАК Потребность,
//	ЕСТЬNULL(ТоварыВРезервеПоЗаказуОстатки.КоличествоОстаток, 0) КАК ВРезервеПодЗаказ,
//	ЕСТЬNULL(ТоварыВРезервеПоЗаказамОстатки.КоличествоОстаток, 0) КАК ВРезервеОбщее
//ПОМЕСТИТЬ ВТ_ОбеспеченностьВрем
//ИЗ
//	//Документ.ЗаказПокупателя.Товары 
//	РегистрНакопления.ЗаказыПокупателей.Остатки КАК ВТ
//	
//		ЛЕВОЕ СОЕДИНЕНИЕ РегистрНакопления.ТоварыНаСкладах.Остатки КАК ТоварыНаСкладахОстатки
//		ПО (ТоварыНаСкладахОстатки.Номенклатура = ВТ.Номенклатура)
//			И (ТоварыНаСкладахОстатки.ХарактеристикаНоменклатуры = ВТ.ХарактеристикаНоменклатуры)
//			И (ТоварыНаСкладахОстатки.СерияНоменклатуры = ВТ.СерияНоменклатуры)
//			//И (ТоварыНаСкладахОстатки.Склад = ВТ.Ссылка.Склад)
//			И (ТоварыНаСкладахОстатки.Склад = ВЫРАЗИТЬ(ВТ.ЗаказНаПроизводство КАК Документ.ЗаказПокупателя).Склад)
//			И (ВЫБОР
//					КОГДА &ОбщиеСклады
//						ТОГДА ИСТИНА
//					ИНАЧЕ ТоварыНаСкладахОстатки.Организация = ВЫРАЗИТЬ(ВТ.ЗаказНаПроизводство КАК Документ.ЗаказПокупателя).Организация
//				КОНЕЦ)
//			
//		//++ #12484
//		//ЛЕВОЕ СОЕДИНЕНИЕ РегистрНакопления.ЗаказыПокупателей.Остатки КАК ЗаказыПокупателейОстатки
//		//ПО (ЗаказыПокупателейОстатки.Номенклатура = ВТ.Номенклатура)
//		//	И (ЗаказыПокупателейОстатки.ХарактеристикаНоменклатуры = ВТ.ХарактеристикаНоменклатуры)
//		//	И (ЗаказыПокупателейОстатки.СерияНоменклатуры = ВТ.СерияНоменклатуры)
//		//	И (ЗаказыПокупателейОстатки.ЗаказНаПроизводство = ВТ.Ссылка)
//					
//		ЛЕВОЕ СОЕДИНЕНИЕ РегистрНакопления.ТоварыВРезервеНаСкладах.Остатки КАК ТоварыВРезервеПоЗаказуОстатки
//		ПО (ТоварыВРезервеПоЗаказуОстатки.Номенклатура = ВТ.Номенклатура)
//			И (ТоварыВРезервеПоЗаказуОстатки.ХарактеристикаНоменклатуры = ВТ.ХарактеристикаНоменклатуры)
//			И (ТоварыВРезервеПоЗаказуОстатки.СерияНоменклатуры = ВТ.СерияНоменклатуры)
//			//И (ТоварыВРезервеПоЗаказуОстатки.ДокументРезерва = ВТ.Ссылка)
//			И (ТоварыВРезервеПоЗаказуОстатки.ДокументРезерва = ВЫРАЗИТЬ(ВТ.ЗаказНаПроизводство КАК Документ.ЗаказПокупателя))
//				
//		ЛЕВОЕ СОЕДИНЕНИЕ РегистрНакопления.ТоварыВРезервеНаСкладах.Остатки КАК ТоварыВРезервеПоЗаказамОстатки
//		ПО (ТоварыВРезервеПоЗаказамОстатки.Номенклатура = ВТ.Номенклатура)
//			И (ТоварыВРезервеПоЗаказамОстатки.ХарактеристикаНоменклатуры = ВТ.ХарактеристикаНоменклатуры)
//			И (ТоварыВРезервеПоЗаказамОстатки.СерияНоменклатуры = ВТ.СерияНоменклатуры)
//		//-- #12484
//		
//ГДЕ
//	//ВТ.Ссылка.ТекущийСтатус = ЗНАЧЕНИЕ(Справочник.СтатусыЗаказовПокупателей.ВРаботе)
//	ВЫРАЗИТЬ(ВТ.ЗаказНаПроизводство КАК Документ.ЗаказПокупателя).ТекущийСтатус = ЗНАЧЕНИЕ(Справочник.СтатусыЗаказовПокупателей.ВРаботе)
//	//И НЕ ВТ.Ссылка.Склад = ЗНАЧЕНИЕ(Справочник.Склады.ПустаяССылка)
//	//И НЕ ВТ.Ссылка.ПометкаУдаления
//	И НЕ ВТ.Номенклатура.ВидНоменклатуры = ЗНАЧЕНИЕ(Справочник.ВидыНоменклатуры.Услуга)

//	//И ЕСТЬNULL(ЗаказыПокупателейОстатки.КоличествоОстаток, 0) > 0 // #12484
//	И ЕСТЬNULL(ВТ.КоличествоОстаток, 0) > 0 // #12484

////СГРУППИРОВАТЬ ПО
////	ВТ.Ссылка,
////	ВТ.Номенклатура,
////	ВТ.ХарактеристикаНоменклатуры,
////	ВТ.СерияНоменклатуры
////	ЕСТЬNULL(ТоварыНаСкладахОстатки.КоличествоОстаток, 0)
//;

//////////////////////////////////////////////////////////////////////////////////
//ВЫБРАТЬ РАЗРЕШЕННЫЕ
//	ВТ_ОбеспеченностьВрем.ДокументЗаказ КАК ДокументЗаказ,
//	//++ #12484
//	//СУММА(ВЫБОР
//	//		КОГДА ВТ_ОбеспеченностьВрем.КоличествоОстаток >= ВТ_ОбеспеченностьВрем.Заказано
//	//			ТОГДА 0
//	//		ИНАЧЕ 1
//	//	КОНЕЦ) КАК СостояниеОбеспеченности		
//	СУММА(ВЫБОР
//			КОГДА (ВТ_ОбеспеченностьВрем.Потребность > ВТ_ОбеспеченностьВрем.КоличествоОстаток)
//				ИЛИ (ВТ_ОбеспеченностьВрем.Потребность > ВТ_ОбеспеченностьВрем.КоличествоОстаток - (ВТ_ОбеспеченностьВрем.ВРезервеОбщее - ВТ_ОбеспеченностьВрем.ВРезервеПодЗаказ))
//				ТОГДА 1
//			ИНАЧЕ 0
//		КОНЕЦ) КАК СостояниеОбеспеченности
//	//-- #12484
//ПОМЕСТИТЬ ВТ_Обеспеченность
//ИЗ
//	ВТ_ОбеспеченностьВрем КАК ВТ_ОбеспеченностьВрем

//СГРУППИРОВАТЬ ПО
//	ВТ_ОбеспеченностьВрем.ДокументЗаказ
//;

////////////////////////////////////////////////////////////////////////////////	

ВЫБРАТЬ РАЗРЕШЕННЫЕ
	ДокументЗаказПокупателя.Ссылка КАК Ссылка,
	ДокументЗаказПокупателя.ПометкаУдаления КАК ПометкаУдаления,
	ДокументЗаказПокупателя.Номер КАК Номер,
	ДокументЗаказПокупателя.Дата КАК Дата,
	ДокументЗаказПокупателя.Проведен КАК Проведен,
	ДокументЗаказПокупателя.Автор КАК Автор,
	ДокументЗаказПокупателя.Валюта КАК Валюта,
	ДокументЗаказПокупателя.ВидЦен КАК ВидЦен,
	ДокументЗаказПокупателя.ДатаВходящегоДокументаЭлектронногоОбмена КАК ДатаВходящегоДокументаЭлектронногоОбмена,
	ДокументЗаказПокупателя.ДоговорКонтрагента КАК ДоговорКонтрагента,
	ДокументЗаказПокупателя.ИсточникЗаказа КАК ИсточникЗаказа,
	ДокументЗаказПокупателя.Комментарий КАК Комментарий,
	ДокументЗаказПокупателя.Контрагент КАК Контрагент,
	ДокументЗаказПокупателя.НомерВходящегоДокументаЭлектронногоОбмена КАК НомерВходящегоДокументаЭлектронногоОбмена,
	ДокументЗаказПокупателя.Организация КАК Организация,
	ДокументЗаказПокупателя.СуммаДокумента КАК СуммаДокумента,
	ДокументЗаказПокупателя.МоментВремени КАК МоментВремени,
	ДокументЗаказПокупателя.Склад КАК Склад,
	ДокументЗаказПокупателя.ТекущийСтатус КАК ТекущийСтатус,
	ДокументЗаказПокупателя.СтатусСборки КАК СтатусСборки,
	ДокументЗаказПокупателя.ОжидаемаяДатаОтгрузки КАК ОжидаемаяДатаОтгрузки,
	ДокументЗаказПокупателя.ОжидаемоеВремяОтгрузки КАК ОжидаемоеВремяОтгрузки,
	ДокументЗаказПокупателя.ОтгрузкаРазрешена КАК ОтгрузкаРазрешена,
	ДокументЗаказПокупателя.НомераПотолков КАК НомераПотолков,
	ДокументЗаказПокупателя.НомерРозничногоДоговора КАК НомерРозничногоДоговора,
	ДокументЗаказПокупателя.ЭтоЗаказОтРозницы, // №9387
	ДокументЗаказПокупателя.АдресМонтажа КАК АдресМонтажа,
	ДОБАВИТЬКДАТЕ(ДокументЗаказПокупателя.ОжидаемаяДатаОтгрузки, СЕКУНДА, РАЗНОСТЬДАТ(ДАТАВРЕМЯ(1,1,1), ДокументЗаказПокупателя.ОжидаемоеВремяОтгрузки,СЕКУНДА)) КАК ДатаВремяОтгрузки,
	РАЗНОСТЬДАТ(&ТекДата, ДОБАВИТЬКДАТЕ(ДокументЗаказПокупателя.ОжидаемаяДатаОтгрузки, СЕКУНДА, РАЗНОСТЬДАТ(ДАТАВРЕМЯ(1,1,1), ДокументЗаказПокупателя.ОжидаемоеВремяОтгрузки,СЕКУНДА)), МИНУТА) КАК ВремяДоОтгрузкиВМинутах,
	2 КАК Отгружен,
	0 КАК Оплачено,
	0 КАК КОплате,
	0 КАК ДолгКонтрагента,
	2 КАК СостояниеОплаты,
	-1 КАК Произведен,
	2 КАК ЗаказанВПроизводство,
	-1 КАК Производство,
	-1 КАК СтатусЗакупки, // №7702 индикация закупки
	ЛОЖЬ КАК СМСОтправлено,	
	-1 КАК ПотолкиВНаличии,
	-1 КАК СостояниеОбеспеченности,

	//ЕСТЬNULL(ОплатаОбороты.СуммаРасход, 0) КАК Оплачено,
	//ВЫБОР 
	//	КОГДА НЕ ДокументЗаказПокупателя.ТекущийСтатус = ЗНАЧЕНИЕ(Справочник.СтатусыЗаказовПокупателей.Новый)
	//		И НЕ ДокументЗаказПокупателя.ТекущийСтатус = ЗНАЧЕНИЕ(Справочник.СтатусыЗаказовПокупателей.Отменен)
	//	ТОГДА ДокументЗаказПокупателя.СуммаДокумента - ЕСТЬNULL(ОплатаОбороты.СуммаРасход, 0)
	//	ИНАЧЕ 0
	//КОНЕЦ КАК КОплате,	
	//ДокументЗаказПокупателя.СуммаДокумента - ЕСТЬNULL(ОплатаОбороты.СуммаРасход, 0) КАК КОплате,	

	//ЕСТЬNULL(ВзаиморасчетыСКонтрагентамиОстатки.СуммаОстаток, 0) КАК ДолгКонтрагента,

	//ВЫБОР
	//	КОГДА ЕСТЬNULL(ДокументЗаказПокупателя.СуммаДокумента, 0) = 0
	//			ИЛИ ЕСТЬNULL(ОплатаОбороты.СуммаРасход, 0) = 0
	//		ТОГДА 2
	//	ИНАЧЕ ВЫБОР
	//			КОГДА ЕСТЬNULL(ДокументЗаказПокупателя.СуммаДокумента, 0) <= ЕСТЬNULL(ОплатаОбороты.СуммаРасход, 0)
	//					И ЕСТЬNULL(ОплатаОбороты.СуммаРасход, 0) > 0
	//				ТОГДА 0
	//			ИНАЧЕ 1
	//		КОНЕЦ
	//КОНЕЦ КАК СостояниеОплаты, // #12778 убрано в ПриПолученииДанных

	//++ №7702 комментируем, т.к. переведено в индикацию "Производство"
	//ВЫБОР
	//	КОГДА ЕСТЬNULL(ЗаказыПокупателейВПроизводствеОбороты.КоличествоРасход, 0) = 0
	//		ТОГДА 2
	//	КОГДА ЕСТЬNULL(ЗаказыПокупателейВПроизводствеОбороты.КоличествоРасход, 0) = ЕСТЬNULL(ЗаказыПокупателейВПроизводствеОбороты.КоличествоПриход, 0)
	//		ТОГДА 0
	//	ИНАЧЕ 1
	//КОНЕЦ КАК Произведен,
	//-- №7702

	//ВЫБОР
	//	КОГДА ЕСТЬNULL(ЗаказыПокупателейКОтгрузке.КоличествоПриход, 0) > 0
	//			И ЗаказыПокупателейКОтгрузке.КоличествоРасход < ЗаказыПокупателейКОтгрузке.КоличествоПриход
	//		ТОГДА ИСТИНА
	//	ИНАЧЕ ЛОЖЬ
	//КОНЕЦ КАК НеОтгружен,

	// №7702 индикация производства, #8808 доработано
	//ВЫБОР
	//	   КОГДА ЕСТЬNULL(ЗаказыПокупателейВПроизводствеОбороты.КоличествоПриход, 0) > 0 И ЕСТЬNULL(ЗаказыПокупателейВПроизводствеОбороты.КоличествоРасход, 0) = 0
	//			ТОГДА 2
	//		КОГДА ЕСТЬNULL(ЗаказыПокупателейВПроизводствеОбороты.КоличествоПриход, 0) > 0 И ЕСТЬNULL(ЗаказыПокупателейВПроизводствеОбороты.КоличествоРасход, 0) < ЕСТЬNULL(ЗаказыПокупателейВПроизводствеОбороты.КоличествоПриход, 0)
	//			ТОГДА 1
	//		КОГДА ЕСТЬNULL(ЗаказыПокупателейВПроизводствеОбороты.КоличествоПриход, 0) > 0 И ЕСТЬNULL(ЗаказыПокупателейВПроизводствеОбороты.КоличествоРасход, 0) >= ЕСТЬNULL(ЗаказыПокупателейВПроизводствеОбороты.КоличествоПриход, 0)
	//			ТОГДА 0	
	//		ИНАЧЕ -1
	//КОНЕЦ КАК Производство,


	//ЕСТЬNULL(ВТ_Обеспеченность.СостояниеОбеспеченности, 1) КАК СостояниеОбеспеченности,

	&ОбщиеСклады КАК ОбщиеСклады,
	&ТекДата КАК ТекДата,

	NULL КАК СостояниеОригиналаПервичногоДокумента,
	ИСТИНА КАК ОбщееСостояние,
	0 КАК СостояниеОригиналПолучен	
	, ЗаявкиНаДоставку.АдресДоставки КАК АдресДоставки //nva
	, ЗаявкиНаДоставку.СтатусЗаявкиНаДоставку Как СтатусЗаявкиНаДоставку
ИЗ
	Документ.ЗаказПокупателя КАК ДокументЗаказПокупателя
		//ЛЕВОЕ СОЕДИНЕНИЕ РегистрНакопления.ЗаказыПокупателей.Обороты КАК ЗаказыПокупателейКОтгрузке
		//ПО ДокументЗаказПокупателя.Ссылка = ЗаказыПокупателейКОтгрузке.ЗаказНаПроизводство

		//ЛЕВОЕ СОЕДИНЕНИЕ РегистрНакопления.РасчетыПоЗаказам.Обороты КАК ОплатаОбороты
		//ПО ДокументЗаказПокупателя.Ссылка = ОплатаОбороты.Заказ

		//ЛЕВОЕ СОЕДИНЕНИЕ РегистрНакопления.ВзаиморасчетыСКонтрагентами.Остатки КАК ВзаиморасчетыСКонтрагентамиОстатки
		//ПО ДокументЗаказПокупателя.Контрагент = ВзаиморасчетыСКонтрагентамиОстатки.Контрагент
		//	И ДокументЗаказПокупателя.Организация = ВзаиморасчетыСКонтрагентамиОстатки.Организация

		//левое СОЕДИНЕНИЕ 	РегистрНакопления.ЗаказыПокупателейВПроизводстве.Обороты() КАК ЗаказыПокупателейВПроизводствеОбороты
		//по   ДокументЗаказПокупателя.Ссылка = ЗаказыПокупателейВПроизводствеОбороты.ЗаказПокупателя

		//ЛЕВОЕ СОЕДИНЕНИЕ ВТ_Обеспеченность КАК ВТ_Обеспеченность
		//ПО ДокументЗаказПокупателя.Ссылка = ВТ_Обеспеченность.ДокументЗаказ 
		//nva+++
		ЛЕВОЕ СОЕДИНЕНИЕ (ВЫБРАТЬ
			ЗаявкаНаДоставкуОснования.Основание КАК Основание, 
			ЗаявкаНаДоставкуОснования.Ссылка.Результат КАК СтатусЗаявкиНаДоставку,
			МАКСИМУМ(ВЫРАЗИТЬ(ЗаявкаНаДоставкуОснования.Ссылка.АдресДоставки КАК СТРОКА(100))) КАК АдресДоставки
		ИЗ
			Документ.ЗаявкаНаДоставку.Основания КАК ЗаявкаНаДоставкуОснования

		СГРУППИРОВАТЬ ПО
			ЗаявкаНаДоставкуОснования.Ссылка.Результат,
			ЗаявкаНаДоставкуОснования.Основание) КАК ЗаявкиНаДоставку
		ПО (ДокументЗаказПокупателя.Ссылка = ЗаявкиНаДоставку.Основание)
        //nva---
